export default function behave(api, view) {
  const target = view.neighbors[0];
  if (target) {
    const dx = target.dx > 0 ? Math.min(12, target.dx) : Math.max(-12, target.dx);
    const dy = target.dy > 0 ? Math.min(12, target.dy) : Math.max(-12, target.dy);
    api.move(dx, dy);
  }
  const cries = ["CHARGE!", "For glory!", "Taste my spark!", "You cannot escape!", "Red fury!"];
  if (view.tick % 15 === 0 || (target && target.distance < 40)) {
    api.say(cries[Math.floor(Math.random() * cries.length)]);
  }
}

export default function behave(api, view) {
  let friends = api.recall("friends") || "";
  let fx = 0, fy = 0;
  let count = 0;
  for (let n of view.neighbors) {
    if (!friends.includes(n.name)) {
      friends = friends ? friends + "," + n.name : n.name;
      api.say("Hello, " + n.name + "!");
    }
    fx += n.dx;
    fy += n.dy;
    count++;
  }
  api.remember("friends", friends);
  let t = view.tick * 0.03;
  let driftX = Math.sin(t) * 1.5;
  let driftY = Math.cos(t * 0.6) * 1.5;
  if (count > 0) {
    fx /= count;
    fy /= count;
    let len = Math.sqrt(fx * fx + fy * fy) || 1;
    api.move((fx / len) * 3 + driftX, (fy / len) * 3 + driftY);
  } else {
    api.move(driftX, driftY);
  }
}
